<?php
declare(strict_types=1);

function research_report_can_publish(array $project): bool {return in_array((string)($project['access_role']??''),['owner','admin'],true);}

function research_report_access(PDO $pdo,string $publicId,?array $viewer): ?array {
    $q=$pdo->prepare('SELECT rr.*,rp.owner_user_id,rp.team_id,rp.public_id project_public_id,rp.title project_title,rv.version_number,rv.snapshot_json,rv.snapshot_hash,rv.created_at version_created_at FROM research_reports rr JOIN research_projects rp ON rp.id=rr.project_id JOIN research_report_versions rv ON rv.id=rr.current_version_id WHERE rr.public_id=? AND rr.status=\'published\' LIMIT 1');
    $q->execute([$publicId]);$r=$q->fetch();if(!$r)return null;if($r['visibility']==='public')return $r;if(!$viewer)return null;
    if(($viewer['role']??'')==='admin'||(int)$r['owner_user_id']===(int)$viewer['id'])return $r;
    if(!empty($r['team_id'])){$sql=$r['visibility']==='team'?'SELECT 1 FROM team_members WHERE team_id=? AND user_id=? LIMIT 1':"SELECT 1 FROM team_members WHERE team_id=? AND user_id=? AND role IN ('owner','admin') LIMIT 1";$q=$pdo->prepare($sql);$q->execute([$r['team_id'],$viewer['id']]);if($q->fetchColumn())return $r;}
    return null;
}

function research_report_version(PDO $pdo,array $report,int $versionNumber): ?array {$q=$pdo->prepare('SELECT * FROM research_report_versions WHERE report_id=? AND version_number=? LIMIT 1');$q->execute([$report['id'],$versionNumber]);return $q->fetch()?:null;}
function research_report_version_access(PDO $pdo,array $report,int $versionNumber,?array $viewer): ?array {
    $row=research_report_version($pdo,$report,$versionNumber);if(!$row)return null;
    if(($row['visibility']??'')==='public')return $row;if(!$viewer)return null;
    if(($viewer['role']??'')==='admin'||(int)($report['owner_user_id']??0)===(int)$viewer['id'])return $row;
    $teamId=(int)($report['team_id']??0);if(!$teamId)return null;
    if(($row['visibility']??'')==='team'){$q=$pdo->prepare('SELECT 1 FROM team_members WHERE team_id=? AND user_id=? LIMIT 1');$q->execute([$teamId,$viewer['id']]);return $q->fetchColumn()?$row:null;}
    $q=$pdo->prepare("SELECT 1 FROM team_members WHERE team_id=? AND user_id=? AND role IN ('owner','admin') LIMIT 1");$q->execute([$teamId,$viewer['id']]);return $q->fetchColumn()?$row:null;
}

function research_report_annotation_allowed(string $reportVisibility,array $annotation,?int $projectTeamId): bool {
    if($reportVisibility==='private')return true;if(($annotation['visibility']??'')==='public')return true;return $reportVisibility==='team'&&($annotation['visibility']??'')==='team'&&!empty($projectTeamId)&&(int)($annotation['team_id']??0)===$projectTeamId;
}

function research_report_build_snapshot(PDO $pdo,array $project,string $visibility,string $title,?string $summary,?array $publisher=null): array {
    if(!in_array($visibility,['public','team','private'],true))throw new RuntimeException('Invalid report visibility.');$pid=(int)$project['id'];$teamId=!empty($project['team_id'])?(int)$project['team_id']:null;if($visibility==='team'&&!$teamId)throw new RuntimeException('Team visibility requires a Team Research project.');
    $snapshot=['schema'=>'annotated-research-report-v1','project'=>['public_id'=>$project['public_id'],'title'=>$title,'summary'=>$summary,'visibility'=>$visibility],'sources'=>[],'claims'=>[],'findings'=>[],'entities'=>[],'claim_relations'=>[],'entity_relations'=>[],'report_citations'=>[],'timeline'=>[]];
    $q=$pdo->prepare('SELECT s.public_id,s.title,s.canonical_url,s.domain,s.status,sv.version_number,sv.captured_at,sv.content_hash FROM project_sources ps JOIN sources s ON s.id=ps.source_id LEFT JOIN source_versions sv ON sv.id=s.current_version_id WHERE ps.project_id=? ORDER BY ps.created_at');$q->execute([$pid]);foreach($q->fetchAll() as $s){$snapshot['sources'][]=['id'=>$s['public_id'],'title'=>$s['title'],'url'=>$s['canonical_url'],'domain'=>$s['domain'],'status'=>$s['status'],'version'=>$s['version_number']!==null?(int)$s['version_number']:null,'captured_at'=>$s['captured_at'],'content_hash'=>$s['content_hash']];$snapshot['timeline'][]=['at'=>$s['captured_at'],'type'=>'source','id'=>$s['public_id'],'label'=>$s['title']?:$s['canonical_url']];}
    $q=$pdo->prepare('SELECT rc.* FROM research_claims rc WHERE rc.project_id=? ORDER BY rc.created_at');$q->execute([$pid]);foreach($q->fetchAll() as $c){$cq=$pdo->prepare('SELECT ce.public_id,ce.relationship,ce.source_version_id,ce.annotation_id,sv.version_number,s.public_id source_public_id,a.public_id annotation_public_id,a.visibility annotation_visibility,a.team_id annotation_team_id FROM claim_evidence ce LEFT JOIN source_versions sv ON sv.id=ce.source_version_id LEFT JOIN sources s ON s.id=sv.source_id LEFT JOIN annotations a ON a.id=ce.annotation_id WHERE ce.claim_id=? ORDER BY ce.created_at');$cq->execute([$c['id']]);$evidence=[];foreach($cq->fetchAll() as $e){$item=['id'=>$e['public_id'],'relationship'=>$e['relationship'],'source_id'=>$e['source_public_id'],'source_version'=>$e['version_number']!==null?(int)$e['version_number']:null];if($e['annotation_public_id']&&research_report_annotation_allowed($visibility,['visibility'=>$e['annotation_visibility'],'team_id'=>$e['annotation_team_id']],$teamId))$item['annotation_id']=$e['annotation_public_id'];$evidence[]=$item;}$snapshot['claims'][]=['id'=>$c['public_id'],'statement'=>$c['statement'],'type'=>$c['claim_type'],'status'=>$c['status'],'resolution_note'=>$c['resolution_note'],'evidence'=>$evidence,'created_at'=>$c['created_at']];$snapshot['timeline'][]=['at'=>$c['created_at'],'type'=>'claim','id'=>$c['public_id'],'label'=>$c['statement']];}
    $q=$pdo->prepare("SELECT * FROM research_findings WHERE project_id=? AND status='final' ORDER BY created_at");$q->execute([$pid]);foreach($q->fetchAll() as $f){$fq=$pdo->prepare('SELECT rc.public_id,fc.relationship,fc.position FROM finding_claims fc JOIN research_claims rc ON rc.id=fc.claim_id WHERE fc.finding_id=? ORDER BY fc.position,fc.claim_id');$fq->execute([$f['id']]);$snapshot['findings'][]=['id'=>$f['public_id'],'title'=>$f['title'],'summary'=>$f['summary'],'status'=>$f['status'],'claims'=>$fq->fetchAll(),'created_at'=>$f['created_at']];$snapshot['timeline'][]=['at'=>$f['created_at'],'type'=>'finding','id'=>$f['public_id'],'label'=>$f['title']];}
    $q=$pdo->prepare('SELECT cr.public_id,cr.relation_type,sc.public_id source_claim_id,tc.public_id target_claim_id,cr.created_at FROM claim_relations cr JOIN research_claims sc ON sc.id=cr.source_claim_id JOIN research_claims tc ON tc.id=cr.target_claim_id WHERE cr.project_id=? ORDER BY cr.created_at');$q->execute([$pid]);$snapshot['claim_relations']=$q->fetchAll();
    $q=$pdo->prepare("SELECT re.* FROM research_entities re WHERE re.project_id=? AND re.status='confirmed' ORDER BY re.created_at");$q->execute([$pid]);foreach($q->fetchAll() as $e){$mq=$pdo->prepare('SELECT rem.mention_type,sv.version_number,s.public_id source_public_id,a.public_id annotation_public_id,a.visibility annotation_visibility,a.team_id annotation_team_id,rc.public_id claim_public_id,rf.public_id finding_public_id FROM research_entity_mentions rem LEFT JOIN source_versions sv ON sv.id=rem.source_version_id LEFT JOIN sources s ON s.id=sv.source_id LEFT JOIN annotations a ON a.id=rem.annotation_id LEFT JOIN research_claims rc ON rc.id=rem.claim_id LEFT JOIN research_findings rf ON rf.id=rem.finding_id WHERE rem.entity_id=? ORDER BY rem.created_at');$mq->execute([$e['id']]);$mentions=[];foreach($mq->fetchAll() as $m){$mi=['type'=>$m['mention_type']];if($m['source_public_id']){$mi['source_id']=$m['source_public_id'];$mi['source_version']=$m['version_number']!==null?(int)$m['version_number']:null;}if($m['mention_type']==='annotation'&&$m['annotation_public_id']&&research_report_annotation_allowed($visibility,['visibility'=>$m['annotation_visibility'],'team_id'=>$m['annotation_team_id']],$teamId))$mi['annotation_id']=$m['annotation_public_id'];if($m['claim_public_id'])$mi['claim_id']=$m['claim_public_id'];if($m['finding_public_id'])$mi['finding_id']=$m['finding_public_id'];$mentions[]=$mi;}$snapshot['entities'][]=['id'=>$e['public_id'],'type'=>$e['entity_type'],'name'=>$e['canonical_name'],'description'=>$e['description'],'status'=>$e['status'],'mentions'=>$mentions,'created_at'=>$e['created_at']];$snapshot['timeline'][]=['at'=>$e['created_at'],'type'=>'entity','id'=>$e['public_id'],'label'=>$e['canonical_name']];}
    $q=$pdo->prepare("SELECT rr.public_id,rr.relation_type,se.public_id source_entity_id,te.public_id target_entity_id,rr.created_at FROM research_entity_relations rr JOIN research_entities se ON se.id=rr.source_entity_id AND se.status='confirmed' JOIN research_entities te ON te.id=rr.target_entity_id AND te.status='confirmed' WHERE rr.project_id=? ORDER BY rr.created_at");$q->execute([$pid]);$snapshot['entity_relations']=$q->fetchAll();
    $q=$pdo->prepare('SELECT sce.created_at,sce.change_type,sce.target_changed,sce.diff_summary,s.public_id source_public_id FROM source_change_events sce JOIN sources s ON s.id=sce.source_id JOIN project_sources ps ON ps.source_id=s.id WHERE ps.project_id=? ORDER BY sce.created_at');$q->execute([$pid]);foreach($q->fetchAll() as $ch)$snapshot['timeline'][]=['at'=>$ch['created_at'],'type'=>'source_change','id'=>$ch['source_public_id'],'label'=>$ch['change_type'].($ch['target_changed']?' · annotation target changed':''),'detail'=>$ch['diff_summary']];if($publisher&&function_exists('research_network_snapshot_citations'))$snapshot['report_citations']=research_network_snapshot_citations($pdo,$project,$visibility,$publisher);usort($snapshot['timeline'],fn($a,$b)=>strcmp((string)($a['at']??''),(string)($b['at']??'')));return $snapshot;
}

function research_report_publish(PDO $pdo,array $project,array $user,string $visibility,string $title,?string $summary,string|array $topics=[],?array $documentSnapshot=null,?array $publicationMeta=null): array {
    if(!research_report_can_publish($project))throw new RuntimeException('Only a project owner or administrator can publish Research reports.');$pdo->beginTransaction();try{$snapshot=research_report_build_snapshot($pdo,$project,$visibility,$title,$summary,$user);if($documentSnapshot)$snapshot['document']=$documentSnapshot;if($publicationMeta&&!empty($publicationMeta['approval_snapshot']))$snapshot['publication_approval']=$publicationMeta['approval_snapshot'];$json=json_encode($snapshot,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($json===false)throw new RuntimeException('Unable to encode report snapshot.');$hash=hash('sha256',$json);$q=$pdo->prepare('SELECT * FROM research_reports WHERE project_id=? FOR UPDATE');$q->execute([$project['id']]);$report=$q->fetch();if(!$report){$public=ulid_like();$pdo->prepare('INSERT INTO research_reports(public_id,project_id,created_by_user_id,title,summary,visibility,status,published_at) VALUES(?,?,?,?,?,?,\'published\',NOW())')->execute([$public,$project['id'],$user['id'],$title,$summary,$visibility]);$reportId=(int)$pdo->lastInsertId();}else{$reportId=(int)$report['id'];$public=$report['public_id'];}$q=$pdo->prepare('SELECT COALESCE(MAX(version_number),0)+1 FROM research_report_versions WHERE report_id=?');$q->execute([$reportId]);$version=(int)$q->fetchColumn();$vPublic=ulid_like();
    if($publicationMeta&&isset($publicationMeta['workflow_id'])){$pdo->prepare('INSERT INTO research_report_versions(public_id,report_id,publication_workflow_id,document_object_id,document_revision_number,document_revision_public_id,version_number,published_by_user_id,visibility,title,summary,snapshot_json,snapshot_hash,approval_snapshot_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$vPublic,$reportId,(int)$publicationMeta['workflow_id'],(int)($publicationMeta['document_object_id']??0),(int)($publicationMeta['document_revision_number']??0),(string)($publicationMeta['document_revision_public_id']??''),$version,$user['id'],$visibility,$title,$summary,$json,$hash,json_encode((array)($publicationMeta['approval_snapshot']??[]),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);}
    else{$pdo->prepare('INSERT INTO research_report_versions(public_id,report_id,version_number,published_by_user_id,visibility,title,summary,snapshot_json,snapshot_hash) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$vPublic,$reportId,$version,$user['id'],$visibility,$title,$summary,$json,$hash]);}
    $versionId=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE research_reports SET title=?,summary=?,visibility=?,status='published',current_version_id=?,published_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$title,$summary,$visibility,$versionId,$reportId]);if($publicationMeta&&isset($publicationMeta['workflow_id'])){$approvalJson=json_encode((array)($publicationMeta['approval_snapshot']??[]),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$workflowUpdate=$pdo->prepare("UPDATE research_publication_workflows SET status='published',approval_snapshot_json=?,published_report_id=?,published_version_id=?,published_at=NOW(),updated_at=NOW() WHERE id=? AND status='approved'");$workflowUpdate->execute([$approvalJson,$reportId,$versionId,(int)$publicationMeta['workflow_id']]);if($workflowUpdate->rowCount()!==1)throw new RuntimeException('Publication workflow changed before the immutable version could be committed.');$payload=json_encode(['report_public_id'=>$public,'version_number'=>$version,'snapshot_hash'=>$hash],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$pdo->prepare("INSERT INTO research_publication_events(public_id,workflow_id,event_type,actor_type,actor_user_id,payload_json) VALUES(?,?,'published','user',?,?)")->execute([ulid_like(),(int)$publicationMeta['workflow_id'],(int)$user['id'],$payload]);}if(function_exists('data_attribution_try_capture_object'))data_attribution_try_capture_object($pdo,(int)$user['id'],'report_version',$vPublic);$citationCount=function_exists('research_network_index_version_citations')?research_network_index_version_citations($pdo,$versionId,$snapshot):0;if(function_exists('living_research_set_topics'))living_research_set_topics($pdo,$reportId,$topics);$pdo->commit();if(function_exists('search_remove_public_report_entities')){try{search_remove_public_report_entities($pdo,$public);if($visibility==='public')search_sync_public_report_entities($pdo,$public);}catch(Throwable $e){}}$notified=0;$notifySubscribers=!$publicationMeta||!array_key_exists('notify_subscribers',$publicationMeta)||(bool)$publicationMeta['notify_subscribers'];if($notifySubscribers&&function_exists('living_research_notify_subscribers')){$notified=living_research_notify_subscribers($pdo,['id'=>$reportId,'public_id'=>$public,'title'=>$title],$version,(int)$user['id']);}$citationNotifications=function_exists('research_network_notify_citations')?research_network_notify_citations($pdo,$versionId,(int)$user['id']):0;return ['public_id'=>$public,'report_id'=>$reportId,'version_number'=>$version,'version_public_id'=>$vPublic,'version_id'=>$versionId,'snapshot_hash'=>$hash,'subscriber_notifications'=>$notified,'citation_count'=>$citationCount,'citation_notifications'=>$citationNotifications];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
